Certainly! Below is a simple example of a TCP/IP server in C. This server listens on a specified port (e.g., 8080), accepts a client connection, reads data sent by the client, prints it to the console, and sends a welcome message back to the client.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>     // for close()
#include <arpa/inet.h>  // for sockaddr_in, inet_ntoa()

#define PORT 8080
#define BUFFER_SIZE 1024

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[BUFFER_SIZE] = {0};
    const char *welcome_msg = "Hello from server";

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Forcefully attaching socket to the port
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Setting address and port
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; // Accept connections on all interfaces
    address.sin_port = htons(PORT);

    // Bind socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("Server started. Listening on port %d...\n", PORT);

    // Start listening
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Accept client connection
    if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen)) < 0) {
        perror("accept");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Connection accepted from %s:%d\n",
           inet_ntoa(address.sin_addr), ntohs(address.sin_port));

    // Read data from client
    int valread = read(new_socket, buffer, BUFFER_SIZE - 1);
    if (valread < 0) {
        perror("read");
        close(new_socket);
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    buffer[valread] = '\0';  // Null terminate the string
    printf("Received from client: %s\n", buffer);

    // Send welcome message to client
    send(new_socket, welcome_msg, strlen(welcome_msg), 0);
    printf("Welcome message sent to client\n");

    // Close sockets
    close(new_socket);
    close(server_fd);
    return 0;
}
```

### How to compile and run

```sh
gcc -o tcp_server tcp_server.c
./tcp_server
```

### What this server does:

- Creates a TCP socket and binds it to port 8080.
- Listens for incoming connection requests.
- Accepts one connection.
- Reads data from the client and prints it.
- Sends a welcome message back.
- Closes the connection.

If you want a server that can handle multiple clients or run continuously, let me know!

